/* ABK Credit Management PDF.js compatibility loader.
   Loads PDF.js 3.11.174 in the browser. The selected credit report file is still processed locally and is not uploaded. */
(function () {
  var source = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js";
  if (globalThis.pdfjsLib) return;
  var request = new XMLHttpRequest();
  request.open("GET", source, false);
  request.send(null);
  if ((request.status >= 200 && request.status < 300) || request.status === 0) {
    (0, eval)(request.responseText + "\n//# sourceURL=" + source);
  } else {
    throw new Error("Could not load compatible PDF.js library from " + source + ". HTTP " + request.status + ".");
  }
  if (!globalThis.pdfjsLib) {
    throw new Error("Compatible PDF.js library loaded but did not initialize.");
  }
})();
